```java
// ─── File: src/test/java/com/bank/covariant/CovariantReturnTest.java ───
package com.bank.covariant;

import com.bank.covariant.factory.*;
import com.bank.covariant.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class CovariantReturnTest {

    @Test
    void covariant_childFactoryReturnsSpecificType() {
        SavingsAccountFactory factory = new SavingsAccountFactory();
        SavingsAccount sa = factory.create("SAV001", new BigDecimal("125000"));
        // Returns SavingsAccount — NO cast!
        assertThat(sa.getInterestRate()).isEqualByComparingTo("0.04");
        assertThat(sa.getAccountId()).isEqualTo("SAV001");
    }

    @Test
    void covariant_homeLoanFactoryReturnsSpecificType() {
        HomeLoanFactory factory = new HomeLoanFactory();
        HomeLoan hl = factory.create("HL001", new BigDecimal("5000000"));
        // Returns HomeLoan — NO cast!
        assertThat(hl.getPropertyType()).isEqualTo("RESIDENTIAL");
        assertThat(hl.getTenureYears()).isEqualTo(20);
    }

    @Test
    void covariant_throughParentReferenceReturnsParentType() {
        AccountFactory factory = new SavingsAccountFactory();  // parent reference
        Account account = factory.create("SAV001", new BigDecimal("125000"));
        // Through parent reference: returns Account (compile-time type)
        // But ACTUAL object is SavingsAccount:
        assertThat(account).isInstanceOf(SavingsAccount.class);
        // Need cast to access SavingsAccount-specific methods:
        SavingsAccount sa = (SavingsAccount) account;
        assertThat(sa.getInterestRate()).isEqualByComparingTo("0.04");
    }

    @Test
    void covariant_noCastNeededWithChildReference() {
        SavingsAccountFactory savingsFactory = new SavingsAccountFactory();
        SavingsAccount sa = savingsFactory.create("SAV001", new BigDecimal("125000"));
        // NO CAST! create() returns SavingsAccount directly.
        // Without covariant return: Account a = savingsFactory.create(...); SavingsAccount sa = (SavingsAccount) a;
        assertThat(sa.getInterestRate()).isNotNull();
    }

    @Test
    void covariant_polymorphismStillWorks() {
        AccountFactory baseFactory = new AccountFactory();
        AccountFactory savingsFactory = new SavingsAccountFactory();
        AccountFactory loanFactory = new HomeLoanFactory();

        // All return Account through parent reference — polymorphic:
        Account a1 = baseFactory.create("ACC001", BigDecimal.ZERO);
        Account a2 = savingsFactory.create("SAV001", new BigDecimal("125000"));
        Account a3 = loanFactory.create("HL001", new BigDecimal("5000000"));

        assertThat(a1).isInstanceOf(Account.class);
        assertThat(a2).isInstanceOf(SavingsAccount.class);
        assertThat(a3).isInstanceOf(HomeLoan.class);
        // Covariant return doesn't break polymorphism — parent reference still works!
    }
}
```

sections.s5d_lld:
```
  ═══ OVERRIDE NARROWS THE RETURN TYPE (Java 5+) ═══

  abstract class Account { abstract Account copy(); }
  class SavingsAccount extends Account {
     @Override
     SavingsAccount copy() {          // COVARIANT: Savings <: Account
        return new SavingsAccount(this);
     }
  }

  class AccountFactory { Account create(){ return new Account(); } }
  class SavingsFactory extends AccountFactory {
     @Override
     SavingsAccount create(){ return new SavingsAccount(); } // narrower OK
  }

  SavingsFactory f = new SavingsFactory();
  SavingsAccount s = f.create();     // no downcast — compiler knows the type

  Legal because SavingsAccount IS-A Account (subtype).
  Returning a SUPERtype or unrelated type → compile error.

  SOLID: LSP preserved — the narrowed return still satisfies the base contract.
  Pattern: Factory Method; covariance removes caller-side casting boilerplate.
```
